// Generated by scripts/build-share-site. GitHub Pages serves 404.html for every unknown path, so this script
// answers /d/c/<code>: it reads the code, fetches that SharedDrink from the app's public iCloud database with
// CloudKit JS, and shows it. Everything it shows is set as text, never as HTML.
(function () {
  "use strict";
  var ALPHABET = "0123456789bcdfghjklmnpqrstvwxyz";
  var LENGTH = 8;
  var SECTIONS = ["loading", "drink", "gone", "offline", "missing"];
  function show(id) {
    SECTIONS.forEach(function (name) { document.getElementById(name).hidden = name !== id; });
  }
  function utf8(binary) {
    var bytes = new Uint8Array(binary.length);
    for (var i = 0; i < binary.length; i++) { bytes[i] = binary.charCodeAt(i); }
    return new TextDecoder().decode(bytes);
  }
  function strings(field, max) {
    var list = field && Array.isArray(field.value) ? field.value : [];
    return list.filter(function (s) { return typeof s === "string"; }).slice(0, max)
      .map(function (s) { return s.slice(0, 300); });
  }
  function fill(id, items) {
    var list = document.getElementById(id);
    items.forEach(function (text) {
      var item = document.createElement("li");
      item.textContent = text;
      list.appendChild(item);
    });
  }
  function render(name, ingredients, steps) {
    document.getElementById("name").textContent = name;
    document.title = name + " · Dranks";
    fill("ingredients", ingredients);
    fill("steps", steps);
    show("drink");
  }

  var match = location.pathname.match(/^\/d\/c\/([^\/]*)\/?$/);
  if (!match) { document.title = "Page not found · Dranks"; show("missing"); return; }
  var code = match[1].toLowerCase();
  var valid = code.length === LENGTH && code.split("").every(function (ch) { return ALPHABET.indexOf(ch) >= 0; });
  if (!valid) { show("gone"); return; }
  if (typeof CloudKit === "undefined" || !window.DRANKS) { show("offline"); return; }
  try {
    CloudKit.configure({ containers: [{
      containerIdentifier: window.DRANKS.container,
      apiTokenAuth: { apiToken: window.DRANKS.apiToken, persist: false },
      environment: window.DRANKS.environment
    }] });
  } catch (e) { show("offline"); return; }
  CloudKit.getDefaultContainer().publicCloudDatabase.fetchRecords([code]).then(function (response) {
    if (response.hasErrors) {
      var error = response.errors[0] || {};
      var reason = error.ckErrorCode || error.serverErrorCode;
      show(reason === "NOT_FOUND" || reason === "UNKNOWN_ITEM" ? "gone" : "offline");
      return;
    }
    var record = response.records && response.records[0];
    if (!record || record.recordType !== "SharedDrink") { show("gone"); return; }
    var fields = record.fields || {};
    var recipe;
    try { recipe = JSON.parse(utf8(atob(fields.recipeData.value))); } catch (e) { show("gone"); return; }
    if (!recipe || typeof recipe.name !== "string") { show("gone"); return; }
    render(recipe.name.slice(0, 80),
           strings(fields.ingredientLines, 12),
           strings(fields.stepLines, 30));
  }, function () { show("offline"); });
})();
